// Station -> code against RoboDK 5.9.4's own MakeProgram (tests/fixtures/robodk_gt/code/robodk_generated_code.tgz):
// a RoboDK Library station is imported (C:/RoboDK/Library), each program RoboDK generated is compiled with
// compileForPost and post-processed with the robot's post (the Export dialog's default), and every file RoboDK wrote is
// compared line by line. Tolerances: date / "generated by" lines and blank lines ignored, numbers within `tol`.
import { existsSync, readFileSync } from 'node:fs';
import path from 'node:path';
import { gunzipSync } from 'node:zlib';
import { importRdkBestEffort } from '../src/io/robodk/rdk_container';
import { AssetStore } from '../src/scene/assets';
import { Station, ItemType, Target } from '../src/core/items/item';
import { Robot } from '../src/core/items/robot';
import { Program } from '../src/core/items/program';
import { compileForPost, getPost, PostFile, PostProgram, CompileOptions } from '../src/posts/index';
import { parseRdkJobScript, rdkJobToPostProgram, recordPostCalls, diffRdkCalls } from '../src/posts/rdk_job';
import { ProgramSimulator } from '../src/core/motion/simulator';
import { normLines, tokens } from './posts_gt_util';

export const LIB = 'C:/RoboDK/Library';
const GT_TGZ = path.resolve(__dirname, 'fixtures/robodk_gt/code/robodk_generated_code.tgz');

/** Every file of a .tgz: "<path>" -> bytes (ustar / PAX / GNU long names). */
export function readTgz(file: string): Map<string, Buffer> {
  const tar = gunzipSync(readFileSync(file)), out = new Map<string, Buffer>();
  let longName: string | null = null;   // PAX "path" / GNU long name of the next entry
  for (let off = 0; off + 512 <= tar.length;) {
    let name = tar.subarray(off, off + 100).toString('utf8').replace(/\0.*$/s, '');
    if (!name) break;
    const prefix = tar.subarray(off + 345, off + 500).toString('utf8').replace(/\0.*$/s, '');
    if (prefix) name = `${prefix}/${name}`;
    const size = parseInt(tar.subarray(off + 124, off + 136).toString('utf8').replace(/\0.*$/s, '').trim() || '0', 8);
    const type = String.fromCharCode(tar[off + 156]);
    const data = tar.subarray(off + 512, off + 512 + size);
    if (type === 'x') { const m = data.toString('utf8').match(/\d+ path=([^\n]*)\n/); if (m) longName = m[1]; }
    else if (type === 'L') longName = data.toString('utf8').replace(/\0.*$/s, '');
    else {
      if (type === '0' || type === '\0') out.set((longName ?? name).replace(/^\.\//, ''), data);
      longName = null;
    }
    off += 512 + Math.ceil(size / 512) * 512;
  }
  return out;
}
let gtCache: Map<string, Buffer> | null = null;
/** RoboDK's generated code: "<station>.rdk_/<program>/<file>" -> bytes. */
export function gtCode(): Map<string, Buffer> {
  return (gtCache ??= readTgz(GT_TGZ));
}

// ---- RoboDK MakeProgram from the station as loaded (tests/fixtures/posts_gt/dump_library_loaded.py) ----------------
export const LOADED_TGZ = path.resolve(__dirname, 'fixtures/posts_gt/library_loaded.tgz');
let loadedCache: Map<string, Buffer> | null = null;
/** "<station dir>/<program dir>/<file>" -> bytes: RoboDK's files, its intermediate post scripts (_rdk_job_*.py) and
 * per station _programs.json (program -> {robot, files, make, failed?}). */
export function loadedCode(): Map<string, Buffer> {
  return (loadedCache ??= existsSync(LOADED_TGZ) ? readTgz(LOADED_TGZ) : new Map());
}
/** Station / program folder names of dump_library_loaded.py (Python isalnum: Unicode letters kept). */
export const pySafe = (s: string) => s.replace(/[^\p{L}\p{N}_-]/gu, '_');
export interface LoadedCase {
  program: string;
  file: string;
  /** studio post calls vs RoboDK's intermediate script ('equal', a difference, or '-' without a script: built-ins) */
  events: string;
  /** the studio's post run on RoboDK's own calls vs RoboDK's file */
  post: string;
  /** compile + post vs RoboDK's file */
  e2e: string;
}
const headerCall = (c: { fn: string; args: unknown[] }) => c.fn === 'RunMessage' && /^(Program generated by|Using nominal kinematics)/.test(String(c.args[0]));
/** Compare a Library station's programs with RoboDK's MakeProgram as loaded: events, post on RoboDK's calls, end to end. */
export async function compareLoaded(file: string): Promise<LoadedCase[]> {
  const all = loadedCode();
  const sdir = pySafe(file) + '_';
  const metaB = all.get(`${sdir}/_programs.json`);
  if (!metaB) return [];
  const meta = JSON.parse(metaB.toString('utf8'));
  const st = await loadLibraryStation(file);
  const out: LoadedCase[] = [];
  for (const [name, m] of Object.entries<any>(meta.programs)) {
    const pdir = `${sdir}/${pySafe(name)}`;
    if (m.failed) { out.push({ program: name, file: '-', events: '-', post: '-', e2e: `RoboDK: ${m.failed}` }); continue; }
    const prog = st.itemsOfType<Program>(ItemType.PROGRAM).find((x) => x.name === name);
    const files = (m.files as string[]).filter((x) => !/\.urp$/i.test(x));
    if (!prog) { for (const f of files) out.push({ program: name, file: f, events: '-', post: '-', e2e: 'no such program in the studio' }); continue; }
    const robot = prog.robot() instanceof Robot ? (prog.robot() as Robot) : null;
    const post = robot ? getPost(robot.postProcessor) : undefined;
    const jobKey = [...all.keys()].find((k) => k.startsWith(`${pdir}/_rdk_job_`));
    const job = jobKey ? parseRdkJobScript(all.get(jobKey)!.toString('utf8')) : null;
    let compiled: PostProgram | null = null, events = '-', onRdk: PostFile[] | null = null, gen: PostFile[] | null = null, err = '';
    try { compiled = compileForPost(st, prog); } catch (e: any) { err = `compile failed: ${e.message}`; }
    if (compiled && job) events = diffRdkCalls(job.programs, recordPostCalls(compiled), 0.011, headerCall) ?? 'equal';
    if (post && job) { try { onRdk = post.generate(rdkJobToPostProgram(job, robot), { headerComments: false }); } catch (e: any) { onRdk = null; err ||= `post on RoboDK's calls failed: ${e.message}`; } }
    if (post && compiled) { try { gen = post.generate(compiled, { headerComments: rdkHeader(robot?.name ?? '') }); } catch (e: any) { err ||= `post failed: ${e.message}`; } }
    const cmp = (g: PostFile[] | null, f: string) => {
      if (!g) return err || 'no post';
      const mine = g.find((q) => q.name.toLowerCase() === f.toLowerCase());
      return mine ? diffTolerant(all.get(`${pdir}/${f}`)!.toString('latin1'), mine.content) ?? 'equal' : `missing (studio wrote ${g.map((q) => q.name).join(', ')})`;
    };
    for (const f of files) out.push({ program: name, file: f, events, post: job ? cmp(onRdk, f) : '-', e2e: cmp(gen, f) });
  }
  return out;
}
/** The GT folder name RoboDK used for a Library file. */
export const gtStationDir = (file: string) => `${file.replace(/[^A-Za-z0-9.-]/g, '_')}_`;

export async function loadLibraryStation(file: string): Promise<Station> {
  const b = readFileSync(`${LIB}/${file}`);
  const { station } = await importRdkBestEffort(b.buffer.slice(b.byteOffset, b.byteOffset + b.byteLength), file, new AssetStore());
  return station;
}

/** Tolerant line equality: case-insensitive text tokens, numbers within tol. */
export function sameLine(a: string, b: string, tol: number): boolean {
  const ta = tokens(a.toLowerCase()), tb = tokens(b.toLowerCase());
  return ta.length === tb.length && ta.every((t, k) => (typeof t === 'number' && typeof tb[k] === 'number' ? Math.abs(t - (tb[k] as number)) <= tol : t === tb[k]));
}
/** First differing line (null = equal). */
export function diffTolerant(expected: string, actual: string, tol = 0.011): string | null {
  const a = normLines(expected), b = normLines(actual);
  for (let i = 0; i < Math.max(a.length, b.length); i++) {
    if (a[i] === undefined || b[i] === undefined) return `line ${i + 1}: expected "${a[i] ?? '<end>'}" got "${b[i] ?? '<end>'}"`;
    if (!sameLine(a[i], b[i], tol)) return `line ${i + 1}: expected "${a[i]}" got "${b[i]}"`;
  }
  return null;
}

export interface CodeCase { program: string; file: string; status: 'equal' | 'diff' | 'missing' | 'no-program' | 'skipped'; detail?: string; post?: string }

/**
 * The header RoboDK writes ("Program generated by RoboDK v5.9.4 for <robot> on <date>"): the studio names itself there;
 * the comparison generates with RoboDK's wording so that posts which split comments into fixed-width lines (Motoman
 * 30-character comments) break them at the same places. Date / "generated by" lines are ignored anyway.
 */
export const rdkHeader = (robot: string) => [`Program generated by RoboDK v5.9.4 for ${robot} on 25/10/2026 03:00:00`, 'Using nominal kinematics.'];

/**
 * RoboDK's Item.Update() before MakeProgram (how dump_gt.py wrote robodk_generated_code.tgz): the program is simulated
 * from where the robots stand and the robot stays at its end for the next program. Returns the joints the simulation
 * reached per move instruction of the program itself (RoboDK's Update does not change the joints of the called
 * programs' targets: 02.h MainProgram writes PickIn1's stored [78.02, ...], PickIn1 alone its simulated [70.15, ...]);
 * compileForPost takes them for targets whose stored joints do not reach the pose (CompileOptions.moveJoints).
 */
export function simulateLikeUpdate(station: Station, program: Program): Map<string, number[]> {
  const sim = new ProgramSimulator(station);
  const start = new Map(station.itemsOfType<Robot>(ItemType.ROBOT).map((r) => [r.id, r.joints()] as [string, number[]]));
  sim.compile(program, start);
  const out = new Map<string, number[]>();
  for (const s of sim.steps) if (s.qTarget && s.instruction.data.kind === 'move' && s.instruction.parent === program) out.set(s.instruction.id, s.qTarget.slice());
  // the program's robot stays at the end; mechanisms (turntables, grippers), driven through called programs or by
  // their own programs, stay where they were (05.b: the GT frames on the turntable are at its initial angle)
  const own = program.robot();
  if (own instanceof Robot && own.dof >= 4) { const j = sim.endJoints(own.id); if (j) own.setJoints(j.slice(0, own.dof)); }
  return out;
}
/** A dump_gt.py ground truth (Python json.dump writes NaN for undefined numbers). */
export function rdkGtJson(file: string): any {
  return JSON.parse(gunzipSync(readFileSync(file)).toString('utf8').replace(/(?<=[:,\[\s])-?(NaN|Infinity)(?=[,\]\s}])/g, 'null'));
}
/** Program order of RoboDK's dump (Item list order of the station, as dump_gt.py iterated it). */
function rdkProgramOrder(file: string): string[] | null {
  const f = path.resolve(__dirname, 'fixtures/robodk_gt', `${gtStationDir(file)}.json.gz`);
  if (!existsSync(f)) return null;
  try { return (rdkGtJson(f).programs ?? []).map((p: { name: string }) => p.name); } catch { return null; }
}

export async function compareStationCode(file: string, only?: string[], tol = 0.011, copts: CompileOptions = {}, mode: 'stored' | 'simulated' = 'stored'): Promise<CodeCase[]> {
  const station = await loadLibraryStation(file);
  const dir = gtStationDir(file);
  const gt = gtCode();
  // "simulated": replay dump_gt.py's sequence: every program, in the station's item order, is simulated (robots chained)
  // and generated right away; joints the simulation gave to targets whose stored joints were stale stay with the targets
  // (RoboDK's Update stores them) for the programs generated later
  const generated = new Map<string, PostFile[] | Error>();
  const generate = (p: Program, moveJoints?: Map<string, number[]>): PostFile[] => {
    const robot = p.robot();
    const post = robot instanceof Robot ? getPost(robot.postProcessor) : undefined;
    if (!post) throw new Error(`no post for ${robot instanceof Robot ? robot.postProcessor : '-'}`);
    const onSimulatedJoints = (tid: string | null, iid: string, j: number[]) => {
      const t = tid ? station.findById(tid) : null;
      if (t instanceof Target) t.setJoints(j);
      else { const ins = p.instructions().find((x) => x.id === iid); if (ins && ins.data.kind === 'move') ins.data.joints = j.slice(); }
    };
    return post.generate(compileForPost(station, p, { ...copts, moveJoints: moveJoints ?? copts.moveJoints, onSimulatedJoints }), { headerComments: rdkHeader(robot instanceof Robot ? robot.name : '') });
  };
  if (mode === 'simulated') {
    for (const name of rdkProgramOrder(file) ?? []) {
      const p = station.itemsOfType<Program>(ItemType.PROGRAM).find((x) => x.name === name);
      if (!p || generated.has(p.name)) continue;
      let sj: Map<string, number[]> | undefined;
      try { sj = simulateLikeUpdate(station, p); } catch { /* program the simulator cannot run */ }
      try { generated.set(p.name, generate(p, sj)); } catch (e: any) { generated.set(p.name, e); }
    }
  }
  const progs = new Map<string, string[]>();
  for (const k of gt.keys()) if (k.startsWith(dir + '/')) { const [, prog, f] = k.split('/'); if (prog && f) progs.set(prog, [...(progs.get(prog) ?? []), f]); }
  const out: CodeCase[] = [];
  const norm = (s: string) => s.replace(/[^A-Za-z0-9]/g, '').toLowerCase();
  for (const [prog, files] of progs) {
    if (only && !only.includes(prog)) continue;
    const p = station.itemsOfType<Program>(ItemType.PROGRAM).find((x) => x.name === prog || norm(x.name) === norm(prog));
    if (!p) { out.push({ program: prog, file: files.join(','), status: 'no-program' }); continue; }
    const robot = p.robot();
    // the post the studio assigns (the station's post, else RoboDK's built-in generator, as the Export dialog does)
    const post = robot instanceof Robot ? getPost(robot.postProcessor) ?? null : null;
    if (!post) { out.push({ program: prog, file: files.join(','), status: 'missing', detail: `no post for ${robot instanceof Robot ? robot.postProcessor : '-'}` }); continue; }
    let gen: PostFile[] = [];
    const pre = generated.get(p.name);
    try { if (pre instanceof Error) throw pre; gen = pre ?? generate(p); } catch (e: any) { out.push({ program: prog, file: files.join(','), status: 'missing', detail: `post failed: ${e.message}`, post: post.id }); continue; }
    for (const f of files) {
      if (/\.urp$/i.test(f)) continue;
      const mine = gen.find((g) => g.name.toLowerCase() === f.toLowerCase()) ?? gen.find((g) => norm(g.name) === norm(f));
      if (!mine) { out.push({ program: prog, file: f, status: 'missing', detail: `studio wrote ${gen.map((g) => g.name).join(',')}`, post: post.id }); continue; }
      const d = diffTolerant(gt.get(`${dir}/${prog}/${f}`)!.toString('latin1'), mine.content, tol);
      out.push({ program: prog, file: f, status: d ? 'diff' : 'equal', detail: d ?? undefined, post: post.id });
    }
  }
  return out;
}
export const haveLibrary = (file: string) => existsSync(`${LIB}/${file}`) && existsSync(GT_TGZ);
